    for(let yy=-24;yy<0;yy+=2){const half=Math.round(32*Math.sqrt(1-Math.pow((yy+1)/24,2))/2)*2;rect(x+19-half,y+5+yy,half*2,2,shop?'#e1b5cd':'#efe4ca');}rect(x-5,y-10,15,3,shop?'#ffe0df':'#fff1d5');
    rect(x+4,y-7,31,17,'#415c72');rect(x+7,y-5,25,9,shop?'#ceaccf':'#a6d6c8');rect(x+17,y-5,3,12,'#70888b');
    rect(x+8,y+15,18,22,'#43546b');rect(x+12,y+17,10,16,'#8caaae');rect(x+18,y+25,2,2,'#f2dc9f');
