  function robotSprite(n,x,y,time){const r=M.RESIDENTS.find(r=>r.id===n.id),bob=Math.floor(Math.sin(time*3+n.id.length));ellipse(x+20,y+37,13,4,'#4c5b7144');if(r.explore&&!n.recruited){rect(x+35,y+4,2,29,'#887795');rect(x+35,y+4,14,9,r.color);rect(x+38,y+6,2,5,'#fff0ce');rect(x+15,y+37,12,3,'#ead3bb');}PixelArt.draw(ctx,PixelArt.robot(n.id,chatNpc===n.id&&$('dialog').open?'happy':'happy',time),x,y-3+bob,2);if(n.cargo){rect(x+29,y+24,9,8,'#967563');rect(x+29,y+24,9,2,'#edc99a');}ctx.textAlign='center';ctx.font='bold 10px monospace';const close=M.canChat(state,n.id);if(close){rect(x+1,y-18,38,14,'#fff0ce');ctx.fillStyle='#5d4b68';ctx.fillText(r.name,x+20,y-8);}if(chatNpc===n.id&&$('dialog').open){rect(x+8,y-36,28,15,'#fff0ce');rect(x+15,y-22,5,5,'#fff0ce');ctx.fillStyle='#b66e95';ctx.fillText('♥ ♥',x+22,y-25);}else if(n.talkedDay!==state.day&&close){rect(x+28,y-28,10,10,'#fff0ce');rect(x+32,y-26,2,4,'#b66e95');rect(x+32,y-21,2,1,'#b66e95');}}
