    if(b.type==='landing'){ellipse(x+20,y+30,40,18,'#899ca4');ellipse(x+20,y+27,30,12,'#b2c6be');line(x-6,y+27,x+46,y+27,'#dcd8b6',2);rect(x+12,y-7,17,34,'#e0ded0');rect(x+16,y-13,9,13,'#adc9cc');rect(x+15,y+2,11,8,'#587f94');ctx.fillStyle='#a5b8ba';ctx.beginPath();ctx.moveTo(x+12,y+10);ctx.lineTo(x-2,y+27);ctx.lineTo(x+12,y+25);ctx.moveTo(x+29,y+10);ctx.lineTo(x+43,y+27);ctx.lineTo(x+29,y+25);ctx.fill();return;}
